import sys

def solve():
    T = int(sys.stdin.readline())
    for _ in range(T):
        A, Y, X = map(int, sys.stdin.readline().split())
        if A < Y:
            print(X * (A // Y) + min(X, A % Y + 1))
        else:
            print(X * (A // Y) + X)

solve()
